package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonAnySetter;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.MapperFeature;
import com.fasterxml.jackson.databind.cfg.HandlerInstantiator;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.cfg.MapperConfigImpl;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.BeanUtil;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for POJOPropertiesCollector._removeUnwantedAccessor
 */
public class POJOPropertiesCollector__removeUnwantedAccessor_TriageGen1Test {

    private MapperConfigImpl<?> config;
    private POJOPropertiesCollector collector;
    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        // Using a real MapperConfigImpl to manage MapperFeatures
        config = new MapperConfigImpl<>(MapperFeature.all(), TypeFactory.defaultInstance());
        typeFactory = TypeFactory.defaultInstance();

        // Constructing the protected class via a subclass or mock if possible.
        // Since it's protected, we can create a test-specific subclass.
        collector = new TestablePOJOPropertiesCollector(config, true, typeFactory.constructType(Object.class), null, "");
    }

    /**
     * Subclass to allow testing of protected method.
     */
    private static class TestablePOJOPropertiesCollector extends POJOPropertiesCollector {
        protected TestablePOJOPropertiesCollector(MapperConfig<?> config, boolean forSerialization, 
                                                com.fasterxml.jackson.databind.JavaType type, 
                                                AnnotatedClass classDef, String mutatorPrefix) {
            super(config, forSerialization, type, classDef, mutatorPrefix);
        }

        @Override
        public void _removeUnwantedAccessor(Map<String, POJOPropertyBuilder> props) {
            super._removeUnwantedAccessor(props);
        }
    }

    @Test
    public void testRemoveUnwantedAccessor_WithEmptyMap() {
        Map<String, POJOPropertyBuilder> props = new HashMap<>();

        // Should not throw exception
        collector._removeUnwantedAccessor(props);

        verifyNoInteractions();
    }

    @Test
    public void testRemoveUnwantedAccessor_WithProperties_InferMutatorsDisabled() {
        // Ensure INFER_PROPERTY_MUTATORS is disabled
        config.disable(MapperFeature.INFER_PROPERTY_MUTATORS);

        Map<String, POJOPropertyBuilder> props = new HashMap<>();
        POJOPropertyBuilder prop1 = mock(POJOPropertyBuilder.class);
        POJOPropertyBuilder prop2 = mock(POJOPropertyBuilder.class);

        props.put("prop1", prop1);
        props.put("prop2", prop2);

        collector._removeUnwantedAccessor(props);

        // Verify removeNonVisible(false) was called for all properties
        verify(prop1, times(1)).removeNonVisible(false);
        verify(prop2, times(1)).removeNonVisible(false);
    }

    @Test
    public void testRemoveUnwantedAccessor_WithProperties_InferMutatorsEnabled() {
        // Ensure INFER_PROPERTY_MUTATORS is enabled
        config.enable(MapperFeature.INFER_PROPERTY_MUTATORS);

        Map<String, POJOPropertyBuilder> props = new HashMap<>();
        POJOPropertyBuilder prop1 = mock(POJOPropertyBuilder.class);

        props.put("prop1", prop1);

        collector._removeUnwantedAccessor(props);

        // Verify removeNonVisible(true) was called
        verify(prop1, times(1)).removeNonVisible(true);
    }

    @Test
    public void testRemoveUnwantedAccessor_SingleProperty() {
        config.disable(MapperFeature.INFER_PROPERTY_MUTATORS);
        Map<String, POJOPropertyBuilder> props = new HashMap<>();
        POJOPropertyBuilder prop = mock(POJOPropertyBuilder.class);
        props.put("test", prop);

        collector._removeUnwantedAccessor(props);

        verify(prop).removeNonVisible(false);
    }
}
